import{t as e}from"./jsx-runtime-Cx0BB4qO.js";import{n as t}from"./page-kit-pDG3USnn.js";var n=e();function r(){return(0,n.jsx)(t,{title:`Returns & Replacement Policy`,intro:`Your satisfaction with our organic quality is our top priority. We offer a transparent, customer-friendly replacement and refund process.`,sections:[[`1. 7-Day Replacement Guarantee`,`Because food products require strict hygienic integrity, we accept replacement requests within 7 calendar days of delivery in cases of: (a) Damaged or punctured product packaging upon arrival, (b) Incorrect product delivered, (c) Expired or defective batch quality.`],[`2. Non-Returnable Conditions`,`Due to food safety standards, opened or partially consumed food packs cannot be returned unless a verified quality deviation is established by our quality assurance team. Products purchased under clearance sales or custom bulk wholesale orders are non-returnable unless defective.`],[`3. How to Initiate a Return or Replacement`,`To request assistance, please email info@jananiagroproducts.com or send a WhatsApp message to +91 93114 16225 with: (1) Your Order ID (e.g. JAP-260811), (2) Clear photographs/video of the issue, (3) Brief description of the problem. Our team will review and approve replacement within 24 hours.`],[`4. Refund Processing Timelines`,`Upon approval, refunds are initiated back to the original payment source (UPI, Credit/Debit Card, or Bank Account) within 3 to 5 business days. For Cash on Delivery orders, refunds are transferred via direct NEFT/UPI transfer to your bank details.`],[`5. Order Cancellation`,`You can cancel any order prior to dispatch from our warehouse by contacting our support line. Once dispatched and assigned to courier, orders cannot be cancelled mid-transit.`]]})}export{r as component};